 35	/** The map facts the sectors and rumors need; the content's `SeaMapDefinition` fits. */
 36	export interface IntelMapShape {
 37	  readonly widthTiles: number;
 38	  readonly heightTiles: number;
 39	  readonly subUnitsPerTile: number;
 40	  readonly islands: readonly { readonly name: string }[];
 41	}
 42	
 43	export interface IntelConfigOptions {
 44	  readonly preset: RulesPresetId;
 45	  readonly finalIsland: IntelPoint;
 46	  readonly controlStartTick?: number;
 47	  /** Defaults to the slice sea. */
 48	  readonly map?: IntelMapShape;
 49	  readonly rules?: IntelRules;
 50	}
 51	
 52	export function requireInteger(value: unknown, name: string): void {
 53	  if (typeof value !== "number" || !Number.isSafeInteger(value)) throw new RangeError(`${name} must be a safe integer, got ${String(value)}`);
 54	}
 55	
 56	export function requireId(value: unknown, name: string): void {
 57	  if (typeof value !== "string" || value.length === 0) throw new RangeError(`${name} must be a non-empty string`);
 58	}
 59	
 60	/** Builds a match's information config from the content rules and the map, refusing invalid rules or maps. */
 61	export function createIntelConfig(options: IntelConfigOptions): IntelConfig {
 62	  const rules = validateIntelRules(options.rules ?? defaultIntelRules);
 63	  if (!rules.ok) throw new RangeError(`invalid intel rules: ${rules.issues.join("; ")}`);
 64	  const map = options.map ?? seaMap;
 65	  const start = options.controlStartTick ?? 0;
 66	  requireInteger(start, "controlStartTick");
 67	  if (start < 0) throw new RangeError(`controlStartTick must not be negative, got ${start}`);
 68	  for (const [value, name] of [
 69	    [map.widthTiles, "widthTiles"],
 70	    [map.heightTiles, "heightTiles"],
 71	    [map.subUnitsPerTile, "subUnitsPerTile"],
 72	  ] as const) {
 73	    requireInteger(value, name);
 74	    if (value <= 0) throw new RangeError(`${name} must be positive, got ${value}`);
 75	  }
 76	  if (map.widthTiles < rules.value.sectorColumns || map.heightTiles < rules.value.sectorRows) {
 77	    throw new RangeError(`a ${map.widthTiles} × ${map.heightTiles} map cannot hold ${rules.value.sectorColumns} × ${rules.value.sectorRows} sectors`);
 78	  }
 79	  requireInteger(options.finalIsland.x, "finalIsland.x");
 80	  requireInteger(options.finalIsland.y, "finalIsland.y");
 81	  return {
 82	    types: presetRubbingTypes(rulesPresets[options.preset]),
 83	    widthTiles: map.widthTiles,
 84	    heightTiles: map.heightTiles,
 85	    subUnitsPerTile: map.subUnitsPerTile,
 86	    sectorColumns: rules.value.sectorColumns,
 87	    sectorRows: rules.value.sectorRows,
 88	    sectorNames: [...rules.value.sectorNames],
 89	    islandNames: map.islands.map((island) => island.name),
 90	    controlStartTick: start,
 91	    finalIsland: { x: options.finalIsland.x, y: options.finalIsland.y },
 92	    carrierIntervalTicks: rules.value.carrierIntervalTicks,
 93	    sectorRevealTick: start + rules.value.sectorRevealTicks,
 94	    carrierRevealTick: start + rules.value.carrierRevealTicks,
 95	  };
 96	}
 97	
 98	/**
 99	 * The sector of a tile: the map's columns and rows are cut into `sectorColumns` × `sectorRows` bands by integer
100	 * division, so every tile lies in exactly one sector and the bands differ in width by at most one tile.
101	 */
102	export function sectorOfTile(config: IntelConfig, tileX: number, tileY: number): number {
103	  const x = Math.min(Math.max(tileX, 0), config.widthTiles - 1);
104	  const y = Math.min(Math.max(tileY, 0), config.heightTiles - 1);
105	  const column = Math.floor((x * config.sectorColumns) / config.widthTiles);
106	  const row = Math.floor((y * config.sectorRows) / config.heightTiles);
107	  return row * config.sectorColumns + column;
108	}
109	
110	/** The sector of a sub-unit position: that of its tile. A position off the map counts in the nearest edge sector. */
111	export function sectorOf(config: IntelConfig, position: IntelPoint): number {
112	  return sectorOfTile(config, Math.floor(position.x / config.subUnitsPerTile), Math.floor(position.y / config.subUnitsPerTile));
113	}
114	
115	export function sectorName(config: IntelConfig, sector: number): string {
116	  const name = config.sectorNames[sector];
117	  if (name === undefined) throw new RangeError(`there is no sector ${sector}`);
118	  return name;
119	}
120	
121	// ---------------------------------------------------------------------------------------------------------------------
122	// The world view: what the caller (the match room, from the ledger) tells the step on each tick.
123	
124	/**
125	 * Where a rubbing is, as the ledger's `location` reads once resolved: sealed at a source (its island and position),
126	 * in a recovery cache (its position), owned by a player, or reserved for a player in an unresolved duel.
127	 */
128	export type IntelRubbingPlace =
129	  | { readonly kind: "source"; readonly island: number; readonly x: number; readonly y: number }
130	  | { readonly kind: "cache"; readonly x: number; readonly y: number }
131	  | { readonly kind: "carried"; readonly playerId: string }
132	  | { readonly kind: "duel"; readonly playerId: string };
133	
134	export interface IntelRubbing {
135	  readonly id: string;
136	  readonly type: RubbingType;
137	  readonly place: IntelRubbingPlace;
138	}
139	
140	/** A player still in the match and their ship's position; a carried rubbing is where its carrier is. */
141	export interface IntelPlayerView {
142	  readonly id: string;
143	  readonly x: number;
144	  readonly y: number;
145	}
146	
147	/**
148	 * One world tick as the information rules see it. A player's held types are the types of the rubbings carried by or
149	 * reserved for them, so they cannot disagree with the rubbings; an island is claimed out when no source on it is sealed.
150	 */
151	export interface IntelWorldView {
152	  /** Later than the state's tick; ticks may be skipped. */
153	  readonly tick: number;
154	  readonly players: readonly IntelPlayerView[];
155	  readonly rubbings: readonly IntelRubbing[];
156	}
157	
158	/** A request to buy a targeted rumor (§11). The caller charges the gold only for a `rumor` or `sighting` outcome. */
159	export interface TargetedRumorRequest {
160	  readonly requestId: string;
161	  readonly playerId: string;
162	  readonly type: RubbingType;
163	}
164	
165	/**
166	 * `rumor` and `sighting` deliver something and are charged. `covered` is not charged: this step already gives the
167	 * player that type for free (a free trigger's rumor or sighting), or another request of the same player and type, lower
168	 * by request id, bought it. `capped`, `none` and `duplicate` deliver nothing.
169	 */
170	export type TargetedRumorResult = "rumor" | "sighting" | "covered" | "capped" | "none" | "duplicate";
171	
172	export interface TargetedRumorOutcome {
173	  readonly requestId: string;
174	  readonly result: TargetedRumorResult;
175	}
176	
177	// ---------------------------------------------------------------------------------------------------------------------
178	// The state.
179	
180	/** A journal rumor points at an island (a sealed source) or at a sector (a recovery cache), never at a carrier. */
181	export type IntelLeadTarget = { readonly kind: "island"; readonly island: number } | { readonly kind: "sector"; readonly sector: number };
182	
183	export type IntelLeadReason = "start" | "fresh" | "targeted" | "replacement";
184	
185	/** The three triggers that may ask for a carrier sighting; a start never does. */
186	export type CarrierSightingReason = Exclude<IntelLeadReason, "start">;
187	
188	/** One journal entry. `entry` numbers a player's rumors from 1. */
189	export interface JournalRumor {
190	  readonly entry: number;
191	  readonly type: RubbingType;
192	  readonly target: IntelLeadTarget;
193	  readonly reason: IntelLeadReason;
194	  readonly tick: number;
195	  /** `stale` once the target no longer holds that type; `resolved` once the holder has the type. */
196	  readonly status: "active" | "stale" | "resolved";
197	  readonly closedTick: number | null;
198	}
199	
200	/** One type of a deferred sighting: the free trigger (a loss or a journal replacement) that asked for it and when. */
201	export interface PendingSightingType {
202	  readonly type: RubbingType;
203	  readonly reason: "fresh" | "replacement";
204	  readonly tick: number;
205	}
206	
207	/**
208	 * The one deferred carrier-sighting message a player may have: the types whose free trigger met the cap, or found no
209	 * snapshot entry to read, waiting for the next snapshot boundary. A step's capped free triggers add their types to the set.
210	 */
211	export interface PendingSighting {
212	  /** In type order, each type once, never empty. */
213	  readonly types: readonly PendingSightingType[];
214	}
215	
216	export interface IntelPlayerState {
217	  readonly id: string;
218	  /** The held types as of the last processed tick, in type order; losses and completions are diffs of these. */
219	  readonly held: readonly RubbingType[];
220	  readonly journal: readonly JournalRumor[];
221	  /** Whether the player's final-island route is active (they hold a full set) and whether they ever had one. */
222	  readonly routeActive: boolean;
223	  readonly routeEver: boolean;
224	  /** The boundary of the snapshot current when the player last got a carrier sighting, or -1. */
225	  readonly lastSightingBoundary: number;
226	  /** The deferred sighting message, or null. */
227	  readonly pending: PendingSighting | null;
228	}
229	
230	/** One carried copy at a snapshot. The holder is kept only so a player is never shown their own copy. */
231	export interface CarrierSnapshotEntry {
232	  readonly sector: number;
233	  readonly type: RubbingType;
234	  readonly holder: string;
235	}
236	
237	export interface CarrierSnapshot {
238	  /** k for the boundary `controlStartTick + k × carrierIntervalTicks`. */
239	  readonly boundary: number;
240	  /** The tick whose world view it records (the boundary tick unless ticks were skipped). */
241	  readonly tick: number;
242	  readonly entries: readonly CarrierSnapshotEntry[];
243	}
244	
245	/** The information state: plain integer data that `hashState` covers entirely. */
246	export interface IntelState {
247	  /** The last world tick processed. */
248	  readonly tick: number;
249	  /** The seed of every draw: each (player, type) decision draws from a generator keyed by it, the tick, the player and the type. */
250	  readonly rng: number;
251	  /** Whether control start has been processed. */
252	  readonly started: boolean;
253	  /** Players seen in the last view, by id. */
254	  readonly players: readonly IntelPlayerState[];
255	  /** The latest two snapshots, older first. */
256	  readonly snapshots: readonly CarrierSnapshot[];
257	  readonly finalSectorAnnounced: boolean;
258	  readonly sectorRevealed: boolean;
259	  /** The index j of the last carrier broadcast (`carrierRevealTick + j × carrierIntervalTicks`), or -1. */
260	  readonly lastCarrierBroadcast: number;
261	  /** Every targeted request id answered so far, sorted. */
262	  readonly requestIds: readonly string[];
263	}
264	
265	/** A state before any tick. `tick` must come before control start, so control start is always crossed. */
266	export function createIntelState(config: IntelConfig, seed: number, tick = -1): IntelState {
267	  requireInteger(seed, "seed");
268	  requireInteger(tick, "tick");
269	  if (tick >= config.controlStartTick) throw new RangeError(`the intel state must start before control start (tick ${config.controlStartTick})`);
270	  return {
271	    tick,
272	    rng: seed >>> 0,
273	    started: false,
274	    players: [],
275	    snapshots: [],
276	    finalSectorAnnounced: false,
277	    sectorRevealed: false,
278	    lastCarrierBroadcast: -1,
279	    requestIds: [],
280	  };
281	}
282	
283	// ---------------------------------------------------------------------------------------------------------------------
284	// Messages: every one names its recipients. Bodies never carry a player id, a rubbing id or an exact position, except
285	// the final island's point in a `final-route` to a player holding a full set.
286	
287	export type IntelRecipients =
288	  | { readonly kind: "player"; readonly playerId: string }
289	  | { readonly kind: "players"; readonly playerIds: readonly string[] }
290	  | { readonly kind: "everyone" };
291	
292	export interface SectorRef {
293	  readonly sector: number;
294	  readonly name: string;
295	}
296	
297	export type IntelRumorTarget =
298	  | { readonly kind: "island"; readonly island: number; readonly name: string }
299	  | { readonly kind: "sector"; readonly sector: number; readonly name: string };
300	
301	/** One type of a carrier-sighting message, with the trigger that asked for it. */
302	export interface CarrierSighting {
303	  readonly type: RubbingType;
304	  readonly reason: CarrierSightingReason;
305	  readonly sector: number;
306	  readonly name: string;
307	}
308	
309	export type IntelMessageBody =
310	  /** A journal lead toward a missing type. */
311	  | { readonly kind: "rumor"; readonly tick: number; readonly entry: number; readonly type: RubbingType; readonly reason: IntelLeadReason; readonly target: IntelRumorTarget }
312	  /** One-shot: per type, the sector where a carrier of it was at `seenTick` (the previous snapshot). Never tracked. */
313	  | { readonly kind: "carrier-sighting"; readonly tick: number; readonly seenTick: number; readonly sightings: readonly CarrierSighting[] }
314	  /** A free trigger found nothing to point at. */
315	  | { readonly kind: "no-lead"; readonly tick: number; readonly type: RubbingType; readonly reason: IntelLeadReason }
316	  | { readonly kind: "rumor-stale"; readonly tick: number; readonly entry: number; readonly type: RubbingType }
317	  | { readonly kind: "rumor-resolved"; readonly tick: number; readonly entry: number; readonly type: RubbingType }
318	  /** A first full set exists: the final island's broad sector (§5). */
319	  | { readonly kind: "final-sector"; readonly tick: number; readonly sector: number; readonly name: string }
320	  /** The exact route, to a full-set holder only; `restored` after a lost set is whole again. */
321	  | { readonly kind: "final-route"; readonly tick: number; readonly x: number; readonly y: number; readonly restored: boolean }
322	  | { readonly kind: "final-route-inactive"; readonly tick: number }
323	  /** Minute 20: sectors holding sealed sources and recovery caches. */
324	  | { readonly kind: "sector-reveal"; readonly tick: number; readonly sources: readonly SectorRef[]; readonly caches: readonly SectorRef[] }
325	  /** Minute 28 on: the carriers' sectors and types at the latest snapshot. */
326	  | { readonly kind: "carrier-report"; readonly tick: number; readonly seenTick: number; readonly carriers: readonly (SectorRef & { readonly type: RubbingType })[] };
327	
328	export type IntelMessageKind = IntelMessageBody["kind"];
329	
330	export interface IntelMessage {
331	  readonly to: IntelRecipients;
332	  readonly body: IntelMessageBody;
333	}
334	
335	export interface IntelStepResult {
336	  readonly state: IntelState;
337	  readonly messages: readonly IntelMessage[];
338	  /** One per request, in the order given. */
339	  readonly outcomes: readonly TargetedRumorOutcome[];
340	}
