 97	const DIRECTIONS = [
 98	  [1, 0],
 99	  [1, 1],
100	  [0, 1],
101	  [-1, 1],
102	  [-1, 0],
103	  [-1, -1],
104	  [0, -1],
105	  [1, -1],
106	] as const;
