336	   336	  check(
337	   337	    view: IntelWorldView,
338	   338	    messages: readonly IntelMessage[],
339	   339	    state: IntelState,
340	   340	    requests: readonly TargetedRumorRequest[] = [],
341	   341	    outcomes: readonly TargetedRumorOutcome[] = [],
342	   342	  ): void {
343	   343	    const config = this.config;
344	   344	    const tick = view.tick;
345	   345	    if (tick - this.previousTick > 1 && this.previousTick >= config.controlStartTick) EXERCISED.add("skipped-ticks");
346	   346	    this.previousTick = tick;
347	   347	    const facts = factsOf(config, view);
348	   348	    this.carriersAt.set(tick, facts.carriers);
349	   349	    for (const player of view.players) this.ids.add(player.id);
350	   350	    for (const rubbing of view.rubbings) this.ids.add(rubbing.id);
351	   351	    if (state.players.some((player) => player.pending !== null)) EXERCISED.add("sighting:deferred");
352	   352	    const fail = (message: IntelMessage, why: string): never => {
353	   353	      throw new Error(`tick ${tick}: ${why}: ${JSON.stringify(message)}`);
354	   354	    };
355	   355	    if (tick < config.controlStartTick && messages.length > 0) fail(messages[0]!, "a message before control start");
356	   356	    // Who had already spent this snapshot's sighting before this step.
357	   357	    const snapshotIndex = Math.floor((tick - config.controlStartTick) / config.carrierIntervalTicks);
358	   358	    const cappedBefore = new Set(
359	   359	      tick >= config.controlStartTick && tick < config.carrierRevealTick ? [...facts.players].filter((id) => this.sightings.has(`${id}@${snapshotIndex}`)) : [],
360	   360	    );
361	   361	    const sightedThisStep = new Set<string>();
362	   362	    for (const message of messages) {
363	   363	      const body = message.body;
364	   364	      EXERCISED.add(`message:${body.kind}`);
365	   365	      if (body.tick !== tick) fail(message, "wrong tick");
366	   366	      // Keys: exactly the allowed ones, nested ones from the small sector/target vocabulary.
367	   367	      expect(Object.keys(body).sort()).toEqual([...BODY_KEYS[body.kind]]);
368	   368	      for (const nested of ["target", "sources", "caches", "carriers", "sightings"] as const) {
369	   369	        const value = (body as Record<string, unknown>)[nested];
370	   370	        if (value === undefined) continue;
371	   371	        for (const item of Array.isArray(value) ? value : [value]) {
372	   372	          for (const key of Object.keys(item as object)) if (!NESTED_KEYS.has(key)) fail(message, `nested key ${key}`);
373	   373	        }
374	   374	      }
375	   375	      // No id anywhere in a body.
376	   376	      for (const text of allStrings(body)) if (this.ids.has(text)) fail(message, `the id ${text} leaks`);
377	   377	      // Addressing: broadcasts to everyone, everything else to one player present now.
378	   378	      if (BROADCASTS.has(body.kind)) {
379	   379	        if (message.to.kind !== "everyone") fail(message, "a broadcast addressed to someone");
380	   380	        continue;
381	   381	      }
382	   382	      if (message.to.kind !== "player" || !facts.players.has(message.to.playerId)) fail(message, "not addressed to one present player");
383	   383	      const recipient = (message.to as { playerId: string }).playerId;
384	   384	      const held = facts.held.get(recipient)!;
385	   385	      const complete = config.types.every((type) => held.includes(type));
386	   386	      const key = (entry: number) => `${recipient}#${entry}`;
387	   387	      switch (body.kind) {
388	   388	        case "final-route":
389	   389	          // The only exact position ever sent, and only to a full-set holder.
390	   390	          if (!complete || body.x !== config.finalIsland.x || body.y !== config.finalIsland.y) fail(message, "a route to a player without a full set");
391	   391	          if (body.restored) EXERCISED.add("route:restored");
392	   392	          break;
393	   393	        case "final-route-inactive":
394	   394	          if (complete) fail(message, "a route suspended for a full set");
395	   395	          break;
396	   396	        case "rumor": {
397	   397	          EXERCISED.add(`rumor:${body.reason}`);
398	   398	          EXERCISED.add(`rumor:${body.target.kind}`);
399	   399	          if (held.includes(body.type)) fail(message, "a rumor for a held type");
400	   400	          const target = body.target;
401	   401	          const there =
402	   402	            target.kind === "island"
403	   403	              ? facts.sourceIslands.some((source) => source.type === body.type && source.island === target.island)
404	   404	              : facts.cacheSectors.some((cache) => cache.type === body.type && cache.sector === target.sector);
405	   405	          if (!there) fail(message, "a rumor pointing at nothing");
406	   406	          // Sources before caches: a cache lead only when no sealed source of the type is left outside the journal.
407	   407	          if (target.kind === "sector") {
408	   408	            const journaled = this.activeIslands(recipient, body.type);
409	   409	            if (facts.sourceIslands.some((source) => source.type === body.type && !journaled.has(source.island))) {
410	   410	              fail(message, "a cache rumor while an eligible sealed source existed");
411	   411	            }
412	   412	          }
413	   413	          if (this.rumors.has(key(body.entry))) fail(message, "a journal entry reused");
414	   414	          this.rumors.set(key(body.entry), { type: body.type, closed: false, target });
415	   415	          break;
416	   416	        }
417	   417	        case "rumor-stale":
418	   418	        case "rumor-resolved": {
419	   419	          // Only journal rumors close; a carrier sighting has no entry, so it can never go stale.
420	   420	          const rumor = this.rumors.get(key(body.entry));
421	   421	          if (rumor === undefined || rumor.closed || rumor.type !== body.type) fail(message, "closing no open journal rumor");
422	   422	          rumor!.closed = true;
423	   423	          if (body.kind === "rumor-resolved" && !held.includes(body.type)) fail(message, "resolved without the type");
424	   424	          if (body.kind === "rumor-stale") {
425	   425	            if (held.includes(body.type)) fail(message, "stale although the holder has the type");
426	   426	            const target = rumor!.target as { kind: "island"; island: number } | { kind: "sector"; sector: number };
427	   427	            const there =
428	   428	              target.kind === "island"
429	   429	                ? facts.sourceIslands.some((source) => source.type === body.type && source.island === target.island)
430	   430	                : facts.cacheSectors.some((cache) => cache.type === body.type && cache.sector === target.sector);
431	   431	            if (there) fail(message, "stale while the target still holds the type");
432	   432	          }
433	   433	          break;
434	   434	        }
435	   435	        case "carrier-sighting": {
436	   436	          if (body.sightings.length === 0) fail(message, "a sighting message with no sighting");
437	   437	          if (sightedThisStep.has(recipient)) fail(message, "a second sighting message in one step");
438	   438	          sightedThisStep.add(recipient);
439	   439	          if (new Set(body.sightings.map((sighting) => sighting.type)).size !== body.sightings.length) fail(message, "a type sighted twice in one message");
440	   440	          if (body.sightings.length > 1) EXERCISED.add("sighting:several-types");
441	   441	          if (body.seenTick >= tick) fail(message, "a sighting of the present");
442	   442	          const age = tick - body.seenTick;
443	   443	          const interval = config.carrierIntervalTicks;
444	   444	          if (!this.skipping && (age < interval || age >= 2 * interval)) fail(message, `a sighting ${age} ticks old`);
445	   445	          const then = this.carriersAt.get(body.seenTick);
446	   446	          if (then === undefined) fail(message, "a sighting of a tick never seen");
447	   447	          for (const sighting of body.sightings) {
448	   448	            if (!SIGHTING_REASONS.has(sighting.reason)) fail(message, `a sighting for the reason ${sighting.reason}`);
449	   449	            EXERCISED.add(`sighting:${sighting.reason}`);
450	   450	            if (held.includes(sighting.type)) fail(message, "a sighting for a held type");
451	   451	            if (!then!.some((carrier) => carrier.type === sighting.type && carrier.sector === sighting.sector && carrier.holder !== recipient)) {
452	   452	              fail(message, "a sighting of no other carrier");
453	   453	            }
454	   454	            // Carriers last: a sighting only when no source or cache of the type exists at all.
455	   455	            if (facts.sourceIslands.some((source) => source.type === sighting.type) || facts.cacheSectors.some((cache) => cache.type === sighting.type)) {
456	   456	              fail(message, "a carrier sighting while a source or cache existed");
457	   457	            }
458	   458	          }
459	   459	          if (tick < config.carrierRevealTick) {
460	   460	            const snapshot = `${recipient}@${Math.floor((tick - config.controlStartTick) / interval)}`;
461	   461	            const count = (this.sightings.get(snapshot) ?? 0) + 1;
462	   462	            if (count > 1) fail(message, "a second sighting message in one snapshot");
463	   463	            this.sightings.set(snapshot, count);
464	   464	          }
465	   465	          break;
466	   466	        }
467	   467	        case "no-lead":
468	   468	          if (held.includes(body.type)) fail(message, "a no-lead for a held type");
469	   469	          break;
470	   470	      }
471	   471	    }
472	   472	    this.checkCharges(tick, messages, requests, outcomes);
473	   473	    this.checkPending(tick, facts, messages, state);
474	   474	    this.checkFreeTriggers(tick, facts, messages, state, cappedBefore);
475	   475	    this.previousState = state;
476	   476	  }
