478	   478	  /**
479	   479	   * Every free trigger of this step (a type lost, or a journal rumor gone stale) whose type needs a carrier sighting
480	   480	   * is in this step's sighting message or in the pending set, never in neither; and it waits only when the player's
481	   481	   * sighting was already spent in this snapshot or the previous snapshot shows no other carrier of it. The pending set
482	   482	   * then goes out at the next boundary (`checkPending`).
483	   483	   */
484	   484	  private checkFreeTriggers(tick: number, facts: Facts, messages: readonly IntelMessage[], state: IntelState, cappedBefore: ReadonlySet<string>): void {
485	   485	    const previous = this.previousState;
486	   486	    if (previous === undefined || !previous.started) return;
487	   487	    const older = state.snapshots.length === 2 ? state.snapshots[0]! : undefined;
488	   488	    const olderCarriers = older === undefined ? [] : this.carriersAt.get(older.tick)!;
489	   489	    for (const now of state.players) {
490	   490	      const before = previous.players.find((player) => player.id === now.id);
491	   491	      if (before === undefined) continue;
492	   492	      const held = facts.held.get(now.id)!;
493	   493	      const mine = messages.filter((message) => message.to.kind === "player" && message.to.playerId === now.id).map((message) => message.body);
494	   494	      const triggered = new Set([
495	   495	        ...before.held.filter((type) => !held.includes(type)),
496	   496	        ...mine.flatMap((body) => (body.kind === "rumor-stale" ? [body.type] : [])),
497	   497	      ]);
498	   498	      const sighted = new Set(mine.flatMap((body) => (body.kind === "carrier-sighting" ? body.sightings.map((sighting) => sighting.type) : [])));
499	   499	      for (const type of triggered) {
500	   500	        const needsSighting =
501	   501	          !held.includes(type) &&
502	   502	          !facts.sourceIslands.some((source) => source.type === type) &&
503	   503	          !facts.cacheSectors.some((cache) => cache.type === type) &&
504	   504	          facts.carriers.some((carrier) => carrier.type === type && carrier.holder !== now.id);
505	   505	        if (!needsSighting || sighted.has(type)) continue;
506	   506	        if (!(now.pending?.types.some((pending) => pending.type === type) ?? false)) throw new Error(`tick ${tick}: ${now.id}'s free ${type} trigger was neither sighted nor queued`);
507	   507	        const readable = olderCarriers.some((carrier) => carrier.type === type && carrier.holder !== now.id);
508	   508	        if (readable && !cappedBefore.has(now.id)) throw new Error(`tick ${tick}: ${now.id}'s free ${type} trigger waits although the sighting was not spent`);
509	   509	        EXERCISED.add("sighting:free-deferred");
510	   510	      }
511	   511	      if (sighted.size > 0 && [...triggered].some((type) => sighted.has(type))) EXERCISED.add("sighting:free-same-step");
512	   512	    }
513	   513	  }
