515	   515	  /**
516	   516	   * Charging (§11): per (player, type), at most one request is charged (`rumor` or `sighting`), and only for a lead of
517	   517	   * that type sent in this step with the reason `targeted`. A request is `covered` only when this step sends that
518	   518	   * player a lead of that type, and never charged when that lead is free.
519	   519	   */
520	   520	  private checkCharges(tick: number, messages: readonly IntelMessage[], requests: readonly TargetedRumorRequest[], outcomes: readonly TargetedRumorOutcome[]): void {
521	   521	    const leads = new Map<string, string>();
522	   522	    for (const message of messages) {
523	   523	      if (message.to.kind !== "player") continue;
524	   524	      const body = message.body;
525	   525	      const found = body.kind === "rumor" ? [{ type: body.type, reason: body.reason, kind: "rumor" }] : body.kind === "carrier-sighting" ? body.sightings.map((sighting) => ({ ...sighting, kind: "sighting" })) : [];
526	   526	      for (const { type, reason, kind } of found) leads.set(`${message.to.playerId}/${type}`, `${kind}:${reason}`);
527	   527	    }
528	   528	    const charged = new Map<string, number>();
529	   529	    requests.forEach((request, index) => {
530	   530	      const result = outcomes[index]!.result;
531	   531	      const key = `${request.playerId}/${request.type}`;
532	   532	      const lead = leads.get(key);
533	   533	      const fail = (why: string): never => {
534	   534	        throw new Error(`tick ${tick}: request ${request.requestId} (${key}) ${result}: ${why}`);
535	   535	      };
536	   536	      if (result === "rumor" || result === "sighting") {
537	   537	        charged.set(key, (charged.get(key) ?? 0) + 1);
538	   538	        if (charged.get(key)! > 1) fail("charged twice for one (player, type)");
539	   539	        if (lead !== `${result}:targeted`) fail(`charged although the lead sent is ${lead ?? "nothing"}`);
540	   540	      } else if (result === "covered") {
541	   541	        if (lead === undefined) fail("covered by nothing");
542	   542	      }
543	   543	    });
544	   544	  }
