546	   546	  /** The islands of the player's journal rumors for the type that are still open. */
547	   547	  private activeIslands(playerId: string, type: RubbingType): Set<number> {
548	   548	    const islands = new Set<number>();
549	   549	    for (const [key, rumor] of this.rumors) {
550	   550	      if (!key.startsWith(`${playerId}#`) || rumor.closed || rumor.type !== type) continue;
551	   551	      const target = rumor.target as { kind: string; island?: number };
552	   552	      if (target.kind === "island") islands.add(target.island!);
553	   553	    }
554	   554	    return islands;
555	   555	  }
