557	   557	  /**
558	   558	   * After every step, each player has at most one pending sighting message holding a set of types. At the first
559	   559	   * boundary after a type was deferred, it goes out in a sighting, unless the checker finds it ineligible (held, a
560	   560	   * source or cache exists, or no one else carries it), or finds no other carrier of it in the previous snapshot to
561	   561	   * read, in which case it must still be pending.
562	   562	   */
563	   563	  private checkPending(tick: number, facts: Facts, messages: readonly IntelMessage[], state: IntelState): void {
564	   564	    const fail = (why: string): never => {
565	   565	      throw new Error(`tick ${tick}: ${why}`);
566	   566	    };
567	   567	    for (const player of state.players) {
568	   568	      if (player.pending === null) continue;
569	   569	      const types = player.pending.types.map((pending) => pending.type);
570	   570	      if (types.length === 0) fail(`${player.id} has an empty pending message`);
571	   571	      if (new Set(types).size !== types.length) fail(`${player.id} has a type pending twice`);
572	   572	    }
573	   573	    const previous = this.previousState;
574	   574	    const newest = state.snapshots.at(-1);
575	   575	    if (previous === undefined || newest === undefined || newest.boundary <= (previous.snapshots.at(-1)?.boundary ?? -1)) return;
576	   576	    const older = state.snapshots.length === 2 ? state.snapshots[0]! : undefined;
577	   577	    const olderCarriers = older === undefined ? [] : this.carriersAt.get(older.tick)!;
578	   578	    for (const before of previous.players) {
579	   579	      const now = state.players.find((player) => player.id === before.id);
580	   580	      if (before.pending === null || now === undefined) continue;
581	   581	      const sighted = new Set(
582	   582	        messages.flatMap((message) =>
583	   583	          message.to.kind === "player" && message.to.playerId === before.id && message.body.kind === "carrier-sighting"
584	   584	            ? message.body.sightings.map((sighting) => sighting.type)
585	   585	            : [],
586	   586	        ),
587	   587	      );
588	   588	      for (const { type } of before.pending.types) {
589	   589	        const stillPending = now.pending?.types.some((pending) => pending.type === type) ?? false;
590	   590	        const eligible =
591	   591	          !facts.held.get(before.id)!.includes(type) &&
592	   592	          !facts.sourceIslands.some((source) => source.type === type) &&
593	   593	          !facts.cacheSectors.some((cache) => cache.type === type) &&
594	   594	          facts.carriers.some((carrier) => carrier.type === type && carrier.holder !== before.id);
595	   595	        const readable = olderCarriers.some((carrier) => carrier.type === type && carrier.holder !== before.id);
596	   596	        if (sighted.has(type)) EXERCISED.add("sighting:deferred-delivered");
597	   597	        else if (eligible && readable) fail(`${before.id}'s deferred ${type} sighting was not delivered at the boundary`);
598	   598	        else if (eligible && !stillPending) fail(`${before.id}'s deferred ${type} sighting was dropped while eligible`);
599	   599	        else if (!eligible && stillPending) fail(`${before.id}'s deferred ${type} sighting is still pending although ineligible`);
600	   600	      }
601	   601	    }
602	   602	  }
603	   603	}
