605	   605	/** A seeded shuffle, leaving the input as it is. */
606	   606	function shuffled<T>(items: readonly T[], draw: Draw): T[] {
607	   607	  const out = [...items];
608	   608	  for (let index = out.length - 1; index > 0; index--) {
609	   609	    const other = draw(index + 1);
610	   610	    [out[index], out[other]] = [out[other]!, out[index]!];
611	   611	  }
612	   612	  return out;
613	   613	}
