615	   615	/**
616	   616	 * Adds purchases to a script so steps often carry several: one player buying one type twice, two players buying one
617	   617	 * type, and purchases on the same tick as losses and replacements. Ids stay unique within a step.
618	   618	 */
619	   619	function withPurchases(script: readonly IntelReplayTick[], config: IntelConfig, seed: number): IntelReplayTick[] {
620	   620	  const draw = generator(seed ^ 0x5eed);
621	   621	  let next = 0;
622	   622	  return script.map(({ view, requests }) => {
623	   623	    const extra: TargetedRumorRequest[] = [];
624	   624	    if (view.tick >= config.controlStartTick && view.players.length > 0 && draw(1000) < 120) {
625	   625	      const count = 2 + draw(4);
626	   626	      for (let index = 0; index < count; index++) {
627	   627	        const repeat = extra.length > 0 && draw(3) === 0 ? extra[draw(extra.length)]! : undefined;
628	   628	        const playerId = repeat !== undefined && draw(2) === 0 ? repeat.playerId : view.players[draw(view.players.length)]!.id;
629	   629	        const type = repeat?.type ?? config.types[draw(config.types.length)]!;
630	   630	        extra.push({ requestId: `buy-${next++}`, playerId, type });
631	   631	      }
632	   632	    }
633	   633	    return deepFreeze({ view, requests: [...(requests ?? []), ...extra] });
634	   634	  });
635	   635	}
