683	   683	    expect(QUICK_RULES.carrierRevealTicks % QUICK_RULES.carrierIntervalTicks).toBe(0);
684	   684	  });
685	   685	
686	   686	  for (const scenario of SCENARIOS.filter((candidate) => !candidate.realTimes)) {
687	   687	    it(`give the same messages, outcomes and state for any order of a step's requests and view arrays: ${scenario.name}`, { timeout: 120_000 }, () => {
688	   688	      const { config, script: plain } = setup(scenario);
689	   689	      const script = withPurchases(plain, config, scenario.seed);
690	   690	      const draw = generator(scenario.seed ^ 0xa11ce);
691	   691	      const checker = new Checker(config, scenario.skipPerMille > 0);
692	   692	      const byRequestId = (outcomes: readonly TargetedRumorOutcome[]) => [...outcomes].sort((a, b) => (a.requestId < b.requestId ? -1 : a.requestId > b.requestId ? 1 : 0));
693	   693	      let listed = createIntelState(config, scenario.seed);
694	   694	      let permuted = listed;
695	   695	      let several = 0;
696	   696	      for (const { view, requests } of script) {
697	   697	        const asked = requests ?? [];
698	   698	        const shuffledView: IntelWorldView = { tick: view.tick, players: shuffled(view.players, draw), rubbings: shuffled(view.rubbings, draw) };
699	   699	        const a = stepIntel(config, listed, view, asked);
700	   700	        const b = stepIntel(config, permuted, shuffledView, shuffled(asked, draw));
701	   701	        expect(b.messages).toEqual(a.messages);
702	   702	        expect(byRequestId(b.outcomes)).toEqual(byRequestId(a.outcomes));
703	   703	        // The state hash on every step that asked or said something (hashing every quiet step too is slow), and at the end.
704	   704	        if (asked.length > 0 || a.messages.length > 0) expect(hashState(b.state)).toBe(hashState(a.state));
705	   705	        checker.check(view, a.messages, a.state, asked, a.outcomes);
706	   706	        for (const outcome of a.outcomes) EXERCISED.add(`outcome:${outcome.result}`);
707	   707	        if (asked.length > 1) several++;
708	   708	        listed = a.state;
709	   709	        permuted = b.state;
710	   710	      }
711	   711	      expect(hashState(permuted)).toBe(hashState(listed));
712	   712	      expect(several).toBeGreaterThan(20);
713	   713	    });
714	   714	  }
715	   715	
716	   716	  it("exercise every message kind, outcome and lead path (EXERCISED)", () => {
717	   717	    expect(MUST_EXERCISE.filter((path) => !EXERCISED.has(path))).toEqual([]);
718	   718	  });
719	   719	});
