  private checkCharges(
    tick: number,
    facts: Facts,
    messages: readonly IntelMessage[],
    state: IntelState,
    requests: readonly TargetedRumorRequest[],
    outcomes: readonly TargetedRumorOutcome[],
  ): void {
    const leads = new Map<string, string[]>();
    for (const message of messages) {
      if (message.to.kind !== "player") continue;
      const body = message.body;
      const found = body.kind === "rumor" ? [{ type: body.type, reason: body.reason, kind: "rumor" }] : body.kind === "carrier-sighting" ? body.sightings.map((sighting) => ({ ...sighting, kind: "sighting" })) : [];
      for (const { type, reason, kind } of found) {
        const key = `${message.to.playerId}/${type}`;
        leads.set(key, [...(leads.get(key) ?? []), `${kind}:${reason}`]);
      }
    }
    const previous = this.previousState;
    const crossed = (state.snapshots.at(-1)?.boundary ?? -1) > (previous?.snapshots.at(-1)?.boundary ?? -1);
    const freeCoverage = (playerId: string, type: RubbingType): "broadcast" | "pending" | null => {
      if (tick < this.config.controlStartTick || !facts.players.has(playerId)) return null;
      const carrierOnly =
        !facts.held.get(playerId)!.includes(type) &&
        !facts.sourceIslands.some((source) => source.type === type) &&
        !facts.cacheSectors.some((cache) => cache.type === type) &&
        facts.carriers.some((carrier) => carrier.type === type && carrier.holder !== playerId);
      if (!carrierOnly) return null;
      if (tick >= this.config.carrierRevealTick) return "broadcast";
      const before = previous?.players.find((player) => player.id === playerId);
      return !crossed && (before?.pending?.types.some((pending) => pending.type === type) ?? false) ? "pending" : null;
    };
    const charged = new Map<string, number>();
    requests.forEach((request, index) => {
      const result = outcomes[index]!.result;
      if (result === "duplicate") return;
      const key = `${request.playerId}/${request.type}`;
      const sent = leads.get(key) ?? [];
      const coverage = freeCoverage(request.playerId, request.type);
      const fail = (why: string): never => {
        throw new Error(`tick ${tick}: request ${request.requestId} (${key}) ${result}: ${why}`);
      };
      if (coverage !== null && result !== "covered") fail(`answered although free coverage (${coverage}) holds`);
      if (result === "rumor" || result === "sighting") {
        charged.set(key, (charged.get(key) ?? 0) + 1);
        if (charged.get(key)! > 1) fail("charged twice for one (player, type)");
        if (sent.length !== 1 || sent[0] !== `${result}:targeted`) fail(`charged although the leads sent are ${sent.join(", ") || "nothing"}`);
      } else if (result === "covered") {
        if (sent.length === 0 && coverage === null) fail("covered by nothing");
        if (sent.length === 0) EXERCISED.add(`covered:${coverage}`);
      }
    });
  }

